(function(root){
 'use strict';
 const A=root.MMPI2Audit,C=root.MMPI2Cases,R=root.MMPI2Report,IO=root.MMPI2IO,S=root.MMPI2Sections,D=A.data,esc=A.escape;
 const icons={plus:'M12 5v14M5 12h14',cases:'M4 6h6l2 2h8v12H4zM4 6V4h7l2 2',home:'M3 10l9-7 9 7M5 9v11h5v-6h4v6h5V9',source:'M5 3h10l4 4v14H5zM14 3v5h5M8 12h8M8 16h8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',upload:'M12 17V5M7 10l5-5 5 5M4 17v4h16v-4',edit:'M4 16l12-12 4 4-12 12H4zM14 6l4 4',repeat:'M4 8a8 8 0 0 1 14-2l3 3M21 3v6h-6M20 16a8 8 0 0 1-14 2l-3-3M3 21v-6h6',close:'M5 5l14 14M19 5L5 19',arrow:'M5 12h14M13 6l6 6-6 6',check:'M4 12l5 5L20 6'};
 const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.source}"/></svg>`;
 const btn=(text,action,classes='',attrs='')=>`<button type="button" class="btn ${classes}" data-action="${action}" ${attrs}>${text}</button>`;
 const control=(name,label,value='',type='text',full=false)=>`<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value??'')}" ${type==='number'?'min="18" max="120"':''}></div>`;
 const select=(name,label,value,options)=>{if(value&&!options.some(([v])=>v===value))options=[[value,String(value)],...options];return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;};
 const textarea=(name,label,value='',full=true)=>`<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea></div>`;
 const clinicalFields=[
  ['mentalExam','Examen mental y observación conductual'],['strengths','Recursos y fortalezas'],
  ['diagnosticImpression','Impresión diagnóstica tentativa documentada'],['prognosis','Pronóstico documentado'],
  ['limitations','Limitaciones de la evaluación']
 ];
 const date=v=>v?String(v).slice(0,10).split('-').reverse().join('/'):'Sin fecha';
 let state,loadError='';
 try{const loaded=C.load();state=loaded.state;if(loaded.migration)C.save(state);}catch(e){loadError=e.message;state={cases:[],evaluator:{fullName:'José Alonso Andrade Salazar'},appVersion:S.VERSION};}
 state.questionBank=validateBank(state.questionBank||root.MMPI2QuestionBank?.questions);
 let view='dashboard',tab='datos',activeId=state.currentCaseId||null,page=0,seqItem=1,captureMode='grid',onlyPending=false,group='clinicas',query='',filter='active',aiInput='',promptOptions={anonymize:true,mode:'integral',focus:''},dialogContext=null,toastTimer,installEvent=null;
 const get=()=>state.cases.find(c=>c.id===activeId);
 const notify=(message,error=false)=>{const el=document.getElementById('toast');el.textContent=message;el.className=error?'error':'';el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',error?9000:4500);};
 const persist=next=>{if(loadError)throw new Error('Resuelva el problema de almacenamiento antes de guardar; descargue primero el respaldo original.');try{C.save(next);}catch(e){throw new Error('No se pudo guardar en este navegador. Descargue un respaldo JSON; revise el espacio disponible antes de continuar.');}state=next;};
 function mutate(id,changes){const old=state.cases.find(c=>c.id===id);const c=A.updateCase(old,changes);persist({...state,cases:state.cases.map(x=>x.id===id?c:x)});return c;}
 const openCase=id=>{activeId=id;view='case';tab='datos';page=0;seqItem=1;aiInput=get()?.aiContextualizedReport||'';persist({...state,currentCaseId:id});render();};
 function count(c){const vals=Object.values(c.responses||{});return {registered:vals.filter(v=>[1,2,3].includes(v)).length,answered:vals.filter(v=>v===1||v===2).length,omitted:vals.filter(v=>v===3).length};}
 const statusPill=c=>c.archivedAt?'<span class="pill">Archivado</span>':c.completedAt?`<span class="pill ${A.synthesis(c.scores).blocked?'warn':'good'}">${A.synthesis(c.scores).blocked?'Finalizada · revisar':'Finalizada'}</span>`:'<span class="pill">En captura</span>';
 function shell(content){return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('source')}</div><div><b>MMPI-2</b><small>SUITE CLÍNICA · ${S.VERSION}</small></div></div><nav class="nav" aria-label="Navegación principal">${[['dashboard','home','Panel de casos'],['sources','source','Fuentes y baremos'],['settings','settings','Evaluador y ajustes']].map(([v,i,t])=>`<button data-action="nav" data-view="${v}" class="${view===v||v==='dashboard'&&view==='case'?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('')}</nav><div class="sidebar-bottom"><strong>Evaluación con contexto</strong><span>Registro, puntuaciones, seguimiento e integración profesional.</span><p style="margin-top:18px">${esc(state.evaluator.fullName||'Configure el evaluador')}</p><span>Motor 17.0 · Octubre 2026</span></div></aside><div class="workspace"><header class="topbar"><span class="topbar-title">Práctica clínica / ${view==='case'?'Caso activo':view==='sources'?'Fuentes técnicas':view==='settings'?'Configuración':'Casos'}</span><div class="online"><i class="dot" style="${navigator.onLine?'':'background:#946325'}"></i>${location.protocol==='file:'?'Archivo local':navigator.onLine?'Guardado en este navegador':'Trabajo sin conexión'}</div></header><main id="main" class="main">${loadError?`<div class="alert bad">${esc(loadError)} ${btn('Descargar almacenamiento original','raw-backup','small')}</div>`:''}${content}</main></div></div>`;}
 function casesList(){
  const list=state.cases.filter(c=>(filter==='archived'?!!c.archivedAt:!c.archivedAt)&&(filter==='complete'?!!c.completedAt:filter==='draft'?!c.completedAt:true)).filter(c=>[c.patient.fullName,c.patient.docId,c.patient.occupation].join(' ').toLowerCase().includes(query.toLowerCase())).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));
  if(!list.length)return `<div class="empty"><div style="width:35px;margin:auto;color:#88a3ae">${icon('cases')}</div><h3>${query?'No hay coincidencias':'Un lugar para cada protocolo'}</h3><p>${query?'Cambie la búsqueda o el filtro.':'Cree un caso o importe sus respaldos anteriores para comenzar.'}</p>${!query?btn(icon('plus')+'Nuevo caso','new','primary'):''}</div>`;
  return list.map(c=>{const n=count(c);return `<div class="case-row"><div class="avatar">${esc(c.patient.fullName.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase())}</div><div><div class="case-name">${esc(c.patient.fullName)}</div><div class="case-meta">${date(c.patient.applicationDate)} · ${c.patient.baremo} · ${esc(c.patient.context||'clínico')}${c.reapplicationOf?' · Reaplicación '+c.applicationNumber:''}</div></div><div class="row-status">${statusPill(c)}</div><div class="row-progress"><div class="case-meta">${n.registered} / 567 registrados</div><div class="progress"><i style="width:${n.registered/567*100}%"></i></div></div><div class="actions">${btn('Abrir '+icon('arrow'),'open','primary small',`data-id="${esc(c.id)}"`)}${btn(icon('edit'),'edit','small',`data-id="${esc(c.id)}" aria-label="Editar ${esc(c.patient.fullName)}"`)}</div></div>`;}).join('');
 }
 function dashboard(){const active=state.cases.filter(c=>!c.archivedAt),complete=active.filter(c=>c.completedAt);return `<div class="page-head"><div><div class="eyebrow">Gestión clínica</div><h1>Panel de casos</h1><p>Organice aplicaciones, revise los perfiles y conserve la evolución de cada caso.</p></div><div class="actions">${btn(icon('plus')+'Nuevo caso','new','primary')}${btn(icon('upload')+'Importar JSON','import-cases')}</div></div><div class="stats">${[[active.length,'Casos activos','Aplicaciones registradas'],[active.length-complete.length,'En captura','Puede retomar el registro'],[complete.length,'Finalizadas','Resultados disponibles'],[active.filter(c=>c.reapplicationOf).length,'Reaplicaciones','Protocolos vinculados']].map(([n,t,d])=>`<div class="stat"><span class="stat-label">${t}</span><strong>${n}</strong><span>${d}</span></div>`).join('')}</div><div class="card"><div class="card-heading"><h2>Aplicaciones</h2>${btn(icon('download')+'Respaldar casos','backup','small')}</div><div class="toolbar"><input id="search" aria-label="Buscar casos" placeholder="Buscar por nombre, documento u ocupación" value="${esc(query)}"><select id="case-filter" aria-label="Filtrar casos">${[['active','Activos'],['draft','En captura'],['complete','Finalizados'],['archived','Archivados']].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select></div><div id="case-list">${casesList()}</div></div><div class="footer-note">Los casos se conservan en este navegador. El respaldo JSON permite trasladarlos y conserva las versiones anteriores.</div>`;}
 function caseHeader(c){return `<div class="page-head"><div><button class="text-btn" data-action="nav" data-view="dashboard" style="margin-bottom:18px">Volver a los casos</button><div class="case-title"><div class="avatar">${esc(c.patient.fullName.slice(0,1))}</div><div><h1>${esc(c.patient.fullName)}</h1><div class="case-meta">${date(c.patient.applicationDate)} · Baremo ${c.patient.baremo} · ${esc(c.patient.context||'clínico')} · ${statusPill(c)}</div></div></div></div><div class="actions">${btn(icon('edit')+'Editar caso','edit','',`data-id="${esc(c.id)}"`)}${btn(icon('repeat')+'Reaplicar','reapply')}${btn(icon('download')+'JSON','backup-case')}</div></div><div class="tabs" role="tablist" aria-label="Secciones del caso">${[['datos','Datos del caso'],['capture','Respuestas'],['results','Resultados'],['compare','Seguimiento'],['ai','Impulso con IA'],['report','Informe']].map(([v,t])=>`<button role="tab" aria-selected="${tab===v}" class="${tab===v?'active':''}" data-action="tab" data-tab="${v}">${t}</button>`).join('')}</div>`;}
 function details(c){const p=c.patient;return `<div class="card"><div class="card-heading"><h2>Identificación y aplicación</h2>${statusPill(c)}</div><dl class="info-grid">${[['Documento',p.docId],['Edad en la aplicación',p.age],['Sexo de la tabla',p.sex==='M'?'Hombre':p.sex==='F'?'Mujer':'Sin registrar'],['Nacimiento',date(p.birthDate)],['Escolaridad',p.schooling],['Profesión',p.profession],['Ocupación',p.occupation],['Modalidad',c.modalidad],['Fuente de cálculo',p.calculationSource==='anterior'?'Datos del ZIP anterior':'Manual adjunto octubre 2026'],['Fecha de aplicación',date(p.applicationDate)]].map(([t,v])=>`<div><dt>${t}</dt><dd>${esc(v??'Sin registrar')}</dd></div>`).join('')}</dl>${c.scoringNotice?`<div class="alert">${esc(c.scoringNotice)}</div>`:''}</div>${[['Motivo de evaluación',p.motive],['Antecedentes',p.antecedents],['Historia del caso',p.caseHistory],['Contexto de la solicitud',S.normContext(p)],['Fuentes e información corroborada',p.sources],['Condiciones de aplicación',p.applicationNotes],['Destinatario del informe',p.recipient]].map(([t,v])=>v?`<div class="card"><h3>${t}</h3><div class="narrative">${esc(v)}</div></div>`:'').join('')}<div class="card"><h2>Versiones del caso</h2>${(c.previousReports||[]).length?(c.previousReports||[]).map((r,i)=>`<div class="history-row"><div><strong>${esc(r.reason||'Versión anterior')}</strong><div class="case-meta">${date(r.recordedAt)} · ${esc(r.scoringVersion||'Motor anterior')} · ${r.aiContextualizedReport?'Incluye integración escrita':'Puntuaciones conservadas'}</div></div><div class="actions">${btn('Ver','history-view','small',`data-index="${i}"`)}${r.responses?btn('Restaurar','history-restore','small',`data-index="${i}"`):''}</div></div>`).join(''):'<p class="muted">Las ediciones de aplicaciones finalizadas y los informes previos se conservarán aquí.</p>'}</div><div class="actions">${btn(c.archivedAt?'Recuperar caso':'Archivar caso','archive','small')}</div>`;}
 function capture(c){const n=count(c),items=Array.from({length:567},(_,i)=>i+1).filter(i=>!onlyPending||c.responses[i]!==1&&c.responses[i]!==2),totalPages=Math.max(1,Math.ceil(items.length/30));page=Math.min(page,totalPages-1);
  const rows=items.slice(page*30,page*30+30);return `<div class="card"><div class="capture-top"><div class="progress-block"><h2 style="margin-bottom:4px">Cuestionario y respuestas</h2><div class="case-meta" id="capture-count">${n.registered} / 567 registrados · ${n.omitted} omisiones · ${567-n.registered} pendientes</div><div class="progress"><i style="width:${n.registered/567*100}%"></i></div></div><div class="actions">${btn(icon('download')+'Excel para el evaluado','template')}${btn(icon('upload')+'Importar respuestas','import-responses')}${btn(icon('check')+'Finalizar aplicación','finish','primary')}</div></div>${c.completedAt?'<div class="alert">Aplicación finalizada. Si cambia una respuesta, la versión anterior se conservará y la integración de IA se retirará para revisión.</div>':''}<div class="result-bar"><div class="actions">${btn('Por bloques','capture-grid',captureMode==='grid'?'primary small':'small')}${btn('Modo secuencial','capture-seq',captureMode==='seq'?'primary small':'small')}</div><label class="case-meta"><input type="checkbox" id="only-pending" ${onlyPending?'checked':''}> Solo pendientes y omisiones</label></div><p class="case-meta">Lea cada pregunta y seleccione su respuesta al frente. Una celda vacía queda pendiente; Omitir registra una omisión deliberada. Los cambios se guardan automáticamente.</p>${captureMode==='grid'?`<div class="questionnaire-list"><div class="questionnaire-head"><span>Ítem</span><span>Pregunta</span><span>Respuesta</span></div>${rows.map(i=>`<div class="questionnaire-row"><span class="questionnaire-number">${i}</span><label class="questionnaire-question" id="question-${i}" for="response-${i}">${esc(state.questionBank[i])}</label><select id="response-${i}" class="questionnaire-answer" data-response-item="${i}" aria-label="Respuesta del ítem ${i}" aria-describedby="question-${i}"><option value="0" ${!c.responses[i]?'selected':''}>Seleccionar…</option>${[[1,'Verdadero'],[2,'Falso'],[3,'Omitir']].map(([v,t])=>`<option value="${v}" ${c.responses[i]===v?'selected':''}>${t}</option>`).join('')}</select></div>`).join('')}</div><div class="pagination">${btn('Anterior','page-prev','small',page===0?'disabled':'')}<span class="case-meta">Bloque ${page+1} de ${totalPages} · ${rows.length?rows[0]+'–'+rows.at(-1):'Sin pendientes'}</span><div class="actions"><label for="jump-item" class="case-meta">Ir al ítem</label><input id="jump-item" class="control" type="number" min="1" max="567" value="${rows[0]||1}">${btn('Ir','jump','small')}${btn('Siguiente','page-next','small',page>=totalPages-1?'disabled':'')}</div></div>`:sequential(c,items)}</div>`;}
 function sequential(c,items){if(!items.length)return '<div class="empty">No quedan respuestas pendientes.</div>';if(onlyPending&&!items.includes(seqItem))seqItem=items.find(i=>i>=seqItem)||items[0];return `<div class="sequential"><div class="item-number">ÍTEM ${seqItem} DE 567</div><div class="question">${esc(state.questionBank?.[seqItem]||'Registre la respuesta correspondiente a este ítem del cuadernillo.')}</div><div class="choices">${[[1,'Verdadero'],[2,'Falso'],[3,'Omitir']].map(([v,t])=>`<button data-action="answer" data-item="${seqItem}" data-value="${v}" class="${c.responses[seqItem]===v?'selected':''}">${t}<small style="display:block">${v===1?'V o 1':v===2?'F o 2':'O o 3'}</small></button>`).join('')}</div><p class="case-meta">Al responder se guarda el registro y avanza al siguiente ítem. Puede volver con las flechas.</p><div class="actions" style="justify-content:center">${btn('Anterior','seq-prev','small',seqItem===1?'disabled':'')}${btn('Siguiente','seq-next','small',seqItem===567?'disabled':'')}</div></div>`;}
 function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(t=>`<th scope="col">${esc(t)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
 function results(c){const s=A.synthesis(c.scores),valid=A.validity(c.scores),code=A.profileCode(c.scores),rows=c.scores.filter(r=>D.groups[group].includes(r.code)),m=R.model(c,state.evaluator),graph=m.blocks.find(b=>b.type==='chart'&&b.title===D.labels[group]);return `<div class="results-summary"><div class="card"><div class="eyebrow">Validez del protocolo</div><h2>${s.verdict}</h2><p class="muted">${c.missing?'Captura pendiente: '+c.missing+' ítems sin registrar.':'Los 567 ítems están registrados.'}</p>${s.invalidity.length?`<div class="alert ${s.blocked?'bad':'warn'}"><ul>${s.invalidity.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>`:'<p class="case-meta">Sin avisos automáticos; integrar condiciones de aplicación y entrevista.</p>'}<div class="case-meta">Índice F−K: ${c.fkIndex}. Regla de validez: manual técnico adjunto.</div></div><div class="card"><div class="eyebrow">Perfil clínico</div><h2>${s.blocked||c.missing?'Lectura pendiente':esc(code.code)}</h2><p class="muted">${s.blocked||c.missing?'Revise los indicadores de validez antes de interpretar el código.':esc(code.descriptor)}</p><p class="case-meta">${esc(code.note)}</p><span class="pill">${c.patient.calculationSource==='anterior'?'Fuente: ZIP anterior':'Fuente: manual adjunto'}</span></div></div><div class="card" style="margin-top:20px"><div class="card-heading"><div><h2>Puntuaciones y perfil</h2><p class="case-meta" style="margin:5px 0 0">PD, corrección K, T y referencia normativa de cada escala.</p></div>${btn(icon('download')+'Excel completo','export-xlsx','small')}</div><select id="result-group" class="control group-select" aria-label="Grupo de escalas">${Object.entries(D.groups).map(([g])=>`<option value="${g}" ${group===g?'selected':''}>${esc(D.labels[g])}</option>`).join('')}</select>${graph?`<figure class="chart">${graph.svg}<figcaption>${esc(graph.caption)}</figcaption></figure>`:''}${table(['Escala','Nombre','PD','K añadida','PD+K','T','Nivel / estado','Fuente e ítems'],rows.map(r=>[`<b>${esc(r.code)}</b>`,esc(r.description),r.raw??'—',r.hasK?r.kAdded:'—',r.hasK?r.rawK:'—',`<span class="score-number">${esc(r.t_display)}</span>`,esc(R.tRange(r)),`<small>${esc(r.norm_label)}</small><details><summary>${r.items} ítems · ${r.omitted} sin respuesta</summary><p>${esc(r.matched?.length?'Ítems que suman PD: '+r.matched.join(', '):r.pairs?'Cálculo mediante pares.':'Sin ítems que sumen PD.')}</p><p>${esc(R.briefReading(r,s.blocked||c.missing>0))}</p></details>`]))}<div class="footer-note">${esc(A.groupSummary(c.scores,group))} T≥65: elevación clínica; T=60–64: moderada. Las subescalas se contextualizan con su escala madre.</div></div>${personality(c)}${criticals(c)}`;}
 function personality(c){if(!S.options(c).clusters)return '';const rows=A.clusters(c.scores,c.patient.baremo);if(!rows.length)return '';const blocked=A.synthesis(c.scores).blocked||c.missing;return `<div class="card"><h2>Correspondencia con clústeres DSM-5</h2>${table(['Área','PSY-5 de referencia','T máxima','Nivel descriptivo','Rasgos a explorar'],rows.map(r=>[r.cluster,esc(r.references),r.T??'—',esc(blocked?'Lectura suspendida':r.level),esc(r.traits)]))}<div class="footer-note">Correspondencia conceptual del manual adjunto. No establece trastornos de personalidad. NEGE e INTR pueden reflejar estados agudos; requiere contraste longitudinal, entrevista específica e información de terceros.</div></div>`;}
 function criticals(c){const cr=A.critical(c.responses,c.patient.sex);return `<div class="card"><h2>Ítems críticos</h2>${cr.suicideItems.length?`<div class="alert bad"><b>Indagación directa del riesgo</b><p>Se reconoció contenido suicida explícito en ${cr.suicideItems.join(', ')}. Realice valoración directa y contextual, incluso si el perfil no es interpretable.</p></div>`:''}${table(['Serie','Área','Reconocidos','Concentración','Ítems','Sin respuesta'],cr.rows.map(r=>[esc(r.series),esc(r.name),`${r.count} / ${r.total}`,r.concentration,esc(r.matched.join(', ')||'—'),r.unknown]))}<div class="footer-note">${esc(cr.note)}</div></div>`;}
 function reportCase(){
  const c=get();
  return c ? {...c,reportQuestionBank:state.questionBank} : null;
 }
 function compareView(c){const rc=R.withComparison({...c,comparisonData:[],comparisonNote:'Sin aplicación anterior documentada.'});return `<div class="card"><div class="card-heading"><div><h2>Comparación longitudinal</h2><p class="case-meta" style="margin:5px 0 0">Conserve las condiciones y la fuente de cada aplicación.</p></div><div class="actions">${btn('Registrar aplicación previa','previous-edit','small')}${c.previousAssessment?.responses?btn('Recalcular previo con parámetros actuales','compare-normalize','small'):''}</div></div><div class="alert">${esc(rc.comparisonNote)}</div>${rc.comparisonData.length?table(['Escala','T anterior','T actual','Diferencia T','Lectura descriptiva'],rc.comparisonData.map(r=>[r.code,esc(r.previous),esc(r.current),r.delta??'—',esc(r.label)])):'<div class="empty"><h3>Un segundo protocolo abre la comparación</h3><p>Reaplique el cuestionario o transcriba resultados previos documentados.</p>'+btn('Reaplicar','reapply','primary')+'</div>'}<p class="footer-note">No se convierte de manera aproximada una T de Mf entre claves distintas: faltaría una correspondencia documental fiable. Los resultados con límites ≤/≥ no se restan como valores exactos.</p></div>`;}
 function aiView(c){const v=A.synthesis(c.scores),withContext=S.options(c).requestContext;return `<div class="ai-layout"><div class="card"><div class="step-label">01 · Preparar el encargo</div><h2>Impulso con IA</h2><p class="muted">El prompt usa las secciones seleccionadas en Informe y solicita un JSON con numeración continua. La ficha, las puntuaciones y las figuras se incorporan desde el caso guardado.</p><div class="fields">${select('ai-mode','Tipo de encargo',withContext||promptOptions.mode!=='pericial'?promptOptions.mode:'integral',[['integral','Informe clínico integral'],...(withContext?[['pericial','Informe pericial']]:[]),['seguimiento','Seguimiento'],['auditoria','Revisión técnica']])}<div class="field"><label for="ai-anonymize">Identificadores directos</label><select id="ai-anonymize"><option value="yes" ${promptOptions.anonymize?'selected':''}>Omitir del prompt</option><option value="no" ${!promptOptions.anonymize?'selected':''}>Incluir datos de identificación</option></select></div>${textarea('ai-focus','Foco o pregunta de integración',promptOptions.focus)}</div><p class="case-meta">Revise el contexto narrativo antes de copiarlo: puede permitir identificación indirecta. La aplicación no envía datos a una IA automáticamente.</p><div class="actions">${btn('Vista previa del prompt','prompt-preview')}${btn('Copiar prompt','prompt-copy','primary')}${btn('Descargar TXT','prompt-download')}</div><div class="divider"></div><div class="actions"><a class="btn small" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">Abrir ChatGPT</a><a class="btn small" href="https://claude.ai/" target="_blank" rel="noopener noreferrer">Abrir Claude</a><a class="btn small" href="https://gemini.google.com/" target="_blank" rel="noopener noreferrer">Abrir Gemini</a></div></div><div class="card"><div class="step-label">02 · Integrar y revisar</div><h2>Texto devuelto por la IA</h2>${v.blocked||c.missing?'<div class="alert warn">La integración clínica está suspendida. Puede preparar un prompt de revisión técnica; primero resuelva los avisos del protocolo.</div>':''}<div class="field"><label for="ai-input">Pegue el JSON del informe, Markdown o TXT</label><textarea id="ai-input" placeholder="Pegue aquí el informe completo…">${esc(aiInput)}</textarea></div><div class="actions" style="margin-top:15px">${btn(icon('upload')+'Importar informe','import-ai')}${btn('Guardar integración','ai-save','primary')}</div>${c.aiContextualizedReport?`<div class="divider"></div><p class="case-meta">${c.aiReviewedAt?'Revisión marcada el '+date(c.aiReviewedAt):'Texto guardado pendiente de revisión.'}</p><div class="actions">${btn('Ver informe completo','tab','',`data-tab="report"`)}${btn('Marcar revisión profesional','ai-review','small')}</div>`:''}</div></div>`;}
 function reportView(c){
  const rc=R.withComparison(c),p=c.patient;
  const choices=S.controls.map(([key,label])=>{
   const {checked,disabled,reason}=S.controlState(rc,key);
   return `<label><input type="checkbox" data-report-option="${key}" ${checked?'checked':''} ${disabled?'disabled':''} ${reason?`aria-describedby="hint-${key}"`:''}><span>${label}${reason?`<small class="option-hint" id="hint-${key}">${reason}</small>`:''}</span></label>`;
  }).join('');
  const review=c.aiContextualizedReport?(c.aiReviewedAt?'IA revisada':'IA pendiente de revisión'):'Integración profesional pendiente';
  return `<div class="card">
   <div class="card-heading"><h2>Informe del caso</h2><span class="pill ${c.aiReviewedAt?'good':'warn'}">${review}</span></div>
   <fieldset class="report-sections"><legend>Secciones</legend><div class="check-list">${choices}</div></fieldset>
   <div class="divider"></div>
   <div class="actions">${btn('Word .docx','export-docx','primary')}${btn('Excel .xlsx','export-xlsx')}${btn('HTML','export-html')}${btn('TXT','export-txt')}${btn('Imprimir / PDF','export-pdf')}</div>
   <p class="case-meta" style="margin-top:12px">La vista previa, el prompt y las exportaciones usan la misma selección. Para PDF, elija Guardar como PDF en el diálogo de impresión.</p>
   <iframe id="report-preview" class="report-frame" title="Vista previa completa del informe" sandbox="allow-same-origin allow-modals"></iframe>
  </div><div class="card"><h2>Integración del evaluador</h2>
   <p class="case-meta">Consigne información clínica documentada. El pronóstico se habilita al registrar que hay entrevista suficiente.</p>
   <div class="fields">
    ${textarea('clinicalSummary','Síntesis general del evaluador',c.clinicalSummary||'')}
    ${textarea('recommendations','Recomendaciones',c.recommendations||'')}
    ${clinicalFields.map(([key,label])=>textarea(key,label,p[key]||'')).join('')}
    <label><input id="f-interviewSufficient" type="checkbox" ${S.interview(c)?'checked':''}> Hay entrevista clínica suficiente</label>
   </div><div class="actions" style="margin-top:15px">${btn('Guardar aportes clínicos','clinical-save','primary')}</div>
  </div>`;
 }
 function sources(){const changes=D.sourceConflicts;return `<div class="page-head"><div><div class="eyebrow">Trazabilidad técnica</div><h1>Fuentes y baremos</h1><p>Elija la fuente por caso y consulte las diferencias entre el documento adjunto y los datos del paquete anterior.</p></div></div><div class="card"><h2>Estado de las fuentes</h2><div class="source-list"><div class="source-item"><div><strong>Manual técnico adjunto · Octubre 2026</strong><p class="case-meta">Fuente de cálculo incorporada en la versión 17.1. Claves, pares VRIN/TRIN, tablas de 84 escalas, criterios, códigos e ítems críticos.</p><span class="pill">Transcripción del documento del usuario</span></div><div class="actions"><a class="btn small" href="./documentacion/MMPI2_Manual_tecnico_escalas_claves_baremos.docx" download>Descargar manual</a></div></div><div class="source-item"><div><strong>Datos del ZIP anterior</strong><p class="case-meta">Conservados como referencia. Puede seleccionarlos en la edición del caso. Los componentes de contenido siguen usando esta fuente porque el nuevo manual no contiene sus claves y tablas completas.</p><span class="pill">Referencia anterior disponible</span></div></div></div><div class="alert warn">${esc(D.manual.limitations)}</div></div><div class="stats">${[[changes.keys.length,'Cambios de clave','Filas de escala y dirección'],[changes.norms.length,'Diferencias de tabla','Celdas PD → T'],[changes.pairs.VRIN_added.length,'Patrones VRIN modificados','Pares transcritos del anexo'],[changes.nonmonotonic.length,'Inversiones en US/MX','Chequeo numérico de progresión']].map(([n,t,d])=>`<div class="stat"><span>${t}</span><strong>${n}</strong><span>${d}</span></div>`).join('')}</div><div class="card"><h2>Escenarios normativos</h2>${table(['Baremo','Referencia','Disponibilidad','Límite'],[['Estados Unidos','Tablas de Minnesota','T disponible','Normas externas a Colombia.'],['México','Tablas mexicanas y subescalas con referencia estadounidense','T disponible; fuente por fila','El informe declara las referencias que combina.'],['España','Tablas históricas descritas como inconsistentes','T suspendida','Se conservan respuestas y PD; requiere cotejo fiable con TEA.']])}<p class="footer-note">El manual describe problemas graves en España. Esta versión conserva la suspensión de T del ZIP anterior; no rehabilita esas tablas por medio de asteriscos.</p></div><div class="card"><div class="card-heading"><h2>Diferencias de claves</h2><a class="btn small" href="./auditoria/diferencias-fuentes.json" download>Auditoría JSON completa</a></div>${table(['Escala','Dirección','Añadidos del manual','Retirados del ZIP anterior'],changes.keys.map(r=>[esc(r.scale),r.direction,esc(r.added.join(', ')),esc(r.removed.join(', '))]))}<p class="footer-note">Las diferencias se conservan para cotejo profesional; este registro no acredita cuál de dos transcripciones es la edición normativa oficial.</p></div>`;}
 function settings(){const e=state.evaluator;return `<div class="page-head"><div><div class="eyebrow">Configuración profesional</div><h1>Evaluador y ajustes</h1><p>Los datos y la firma se incorporan al final de cada informe.</p></div></div><form id="evaluator-form" class="card"><h2>Datos del evaluador</h2><div class="fields">${control('fullName','Nombre completo',e.fullName)}${control('email','Correo',e.email,'email')}${control('professionalCard','Tarjeta profesional',e.professionalCard)}${control('professionalReg','Registro profesional',e.professionalReg)}${control('phone','Teléfono',e.phone)}${control('address','Dirección profesional',e.address)}</div><h3>Firma y emisión</h3><div class="fields">${control('issuePlace','Lugar de emisión',e.issuePlace??e.lugarEmision)}${control('institution','Institución / centro',e.institution??e.institucion)}</div><div class="divider"></div><div class="actions">${btn('Guardar datos','settings-save','primary')}${btn('Cargar firma','signature-upload')}${e.signature?btn('Quitar firma','signature-remove','small'):''}</div>${e.signature&&/^data:image\/(png|jpeg|webp);base64,/.test(e.signature)?`<img class="signature-preview" alt="Firma del evaluador" src="${esc(e.signature)}" style="margin-top:16px">`:''}</form><div class="card"><h2>Cuestionario autorizado</h2><p class="muted">Se incluyen los 567 enunciados de su plantilla previa. La app y el Excel para el evaluado utilizan el mismo cuestionario.</p><p class="case-meta">Puede actualizarlo con JSON (<code>id</code>/<code>text</code>) o Excel con columnas Ítem y Pregunta. Los enunciados personales guardados tienen prioridad y se conservan en el respaldo general.</p><div class="actions">${btn('Importar cuestionario','bank-upload')}${btn('Restaurar cuestionario incluido','bank-reset','small')}${state.questionBank?'<span class="pill good">567 enunciados cargados</span>':''}</div></div><div class="card"><h2>Respaldo y recuperación</h2><p class="muted">Use el respaldo general para trasladar casos, evaluador, firma y configuración a otro equipo. Importar los JSON anteriores también funciona.</p><div class="actions">${btn('Descargar respaldo general','backup','primary')}${btn('Importar respaldo','import-cases')}${btn('Descargar respaldo previo a la actualización','raw-backup')}</div></div><div class="card"><h2>Instalación</h2><p class="muted">En un sitio HTTPS puede instalar la suite y usarla sin conexión después de la primera carga. En iPhone o iPad, use Compartir y Añadir a pantalla de inicio.</p><div class="actions">${btn('Instalar aplicación','install')}</div><p class="case-meta" style="margin-top:15px">Si la abre como archivo local, el registro y las descargas funcionan; la instalación y la caché PWA requieren HTTPS o localhost.</p></div>`;}
 function render(){let content='';if(view==='case'&&get()){const c=get();content=caseHeader(c)+({datos:()=>details(c),capture:()=>capture(c),results:()=>results(c),compare:()=>compareView(c),ai:()=>aiView(c),report:()=>reportView(c)}[tab]||(()=>details(c)))();}else if(view==='sources')content=sources();else if(view==='settings')content=settings();else{view='dashboard';content=dashboard();}document.getElementById('app').innerHTML=shell(content);if(tab==='report'&&view==='case'){document.getElementById('report-preview').srcdoc=R.html(reportCase(),state.evaluator);}}
 function dialog(title,body,buttons,context){dialogContext=context;const el=document.getElementById('dialog');el.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="btn small" data-action="dialog-close" aria-label="Cerrar">${icon('close')}</button></div><div class="dialog-body">${body}</div><div class="dialog-actions">${buttons}</div>`;if(!el.open)el.showModal();}
 function editor(id){const c=id?state.cases.find(x=>x.id===id):null,p=c?.patient||{fullName:'',sex:'F',baremo:'US',applicationDate:C.today(),calculationSource:'manual',context:'clinico'};dialog(c?'Editar caso':'Nuevo caso',`<form id="case-form"><div class="section-label">Identificación y aplicación</div><div class="fields three">${control('fullName','Nombre o código del evaluado *',p.fullName)}${control('docId','Documento',p.docId)}${select('sex','Sexo de la tabla normativa',p.sex,[['F','Mujer'],['M','Hombre']])}${control('birthDate','Fecha de nacimiento',p.birthDate,'date')}${control('age','Edad si no registra nacimiento',p.age,'number')}${control('applicationDate','Fecha de aplicación',p.applicationDate,'date')}${select('baremo','Baremo',p.baremo,[['US','Estados Unidos'],['MX','México'],...(p.baremo==='ES'?[['ES','España · T suspendida']]:[])])}${select('calculationSource','Fuente de cálculo',p.calculationSource||'manual',[['manual','Manual adjunto octubre 2026'],['anterior','Datos del ZIP anterior']])}${select('context','Contexto',p.context,[['clinico','Clínico'],['pericial','Pericial'],['laboral','Laboral'],['investigacion','Investigación']])}${select('modalidad','Modalidad',c?.modalidad||'Presencial',[['Presencial','Presencial'],['Virtual supervisada','Virtual supervisada'],['Transcripción de respuestas','Transcripción de respuestas']])}${control('schooling','Escolaridad',p.schooling)}${control('profession','Profesión',p.profession)}${control('occupation','Ocupación',p.occupation)}</div><div class="section-label" style="margin-top:18px">Información clínica y fuentes</div><div class="fields">${textarea('motive','Motivo de evaluación',p.motive||'')}${textarea('antecedents','Antecedentes',p.antecedents||'')}${textarea('caseHistory','Historia del caso',p.caseHistory||'')}${textarea('requestContext','Contexto de la solicitud',S.normContext(p))}${textarea('sources','Fuentes e información corroborada',p.sources||'')}${textarea('applicationNotes','Condiciones de aplicación',p.applicationNotes||'')}${control('recipient','Destinatario del informe',p.recipient,'text',true)}</div><p class="case-meta">La edad se calcula en la fecha de aplicación cuando registra nacimiento. El cambio de respuestas, normas o contexto retira la integración de IA y conserva su versión anterior.</p></form>`,btn('Cancelar','dialog-close')+btn('Guardar caso','case-save','primary'),{type:'editor',id});}
 function previousEditor(){const c=get(),p=c.previousAssessment||{};dialog('Aplicación anterior documentada',`<form id="previous-form"><div class="fields">${control('date','Fecha de la aplicación anterior',p.date,'date')}${select('baremo','Baremo anterior',p.baremo||'unknown',[['unknown','No consta'],['US','Estados Unidos'],['MX','México']])}${select('sex','Sexo de la tabla anterior',p.sex||'unknown',[['unknown','No consta'],['M','Hombre'],['F','Mujer']])}${select('calculationSource','Fuente de cálculo anterior',p.calculationSource||'unknown',[['unknown','No consta'],['manual','Manual adjunto octubre 2026'],['anterior','Datos del ZIP anterior']])}${textarea('text','Puntuaciones T transcritas',p.text||c.patient.previousMMPI2||'')}</div><p class="case-meta">Ejemplo de formato: Hs=65, D=70, Hy=63, TRIN=60F. Registre solo T documentadas. No se convierte una PD sin su baremo y sexo; puede importar el protocolo completo si dispone de respuestas.</p></form>`,btn('Cancelar','dialog-close')+btn('Guardar comparación','previous-save','primary'),{type:'previous'});}
 async function action(name,el){
  const c=get();
  if(name==='nav'){view=el.dataset.view;render();return;}
  if(name==='new'){editor();return;}
  if(name==='open'){openCase(el.dataset.id);return;}
  if(name==='edit'){editor(el.dataset.id||activeId);return;}
  if(name==='dialog-close'){document.getElementById('dialog').close();return;}
  if(name==='case-save'){
   const form=document.getElementById('case-form');if(!form.reportValidity())return;
   const data=Object.fromEntries(new FormData(form)),old=dialogContext.id?state.cases.find(x=>x.id===dialogContext.id):null,modalidad=data.modalidad;delete data.modalidad;
   const patient=C.validatePatient({...old?.patient,...data});
   if(!patient.applicationDate)throw new Error('Registre la fecha de aplicación.');
   if(old){const result=mutate(old.id,{patient,modalidad});activeId=result.id;}
   else{const next=C.create(patient,{modalidad});persist({...state,cases:[next,...state.cases],currentCaseId:next.id});activeId=next.id;}
   document.getElementById('dialog').close();view='case';tab='datos';aiInput=get().aiContextualizedReport||'';render();notify('Caso guardado.');return;
  }
  if(name==='tab'){tab=el.dataset.tab;if(tab==='ai')aiInput=c.aiContextualizedReport||aiInput;render();return;}
  if(name==='backup'||name==='backup-case'){
   const data=name==='backup-case'?c:{mmpi2_cases:state.cases,evaluator:state.evaluator,questionBank:state.questionBank||null,appVersion:S.VERSION,exportedAt:new Date().toISOString()};
   IO.save(JSON.stringify(data,null,2),name==='backup-case'?IO.filename(c)+'_caso.json':'MMPI2_respaldo_'+C.today()+'.json','application/json');notify('Respaldo preparado para descargar.');return;
  }
  if(name==='raw-backup'){const value=localStorage.getItem(C.BACKUP_KEY)||localStorage.getItem('mmpi2-respaldo-antes-v17');if(!value)throw new Error('No existe un respaldo de migración en este navegador.');IO.save(value,'MMPI2_respaldo_previo_actualizacion.json','application/json');return;}
  if(name==='import-cases'){document.getElementById('file-cases').click();return;}
  if(name==='cases-import-confirm'){
   const ctx=dialogContext,mode=document.getElementById('import-mode').value;let next=C.importInto(state,ctx.cases,mode);
   if(document.getElementById('import-settings')?.checked&&ctx.meta.evaluator)next.evaluator=ctx.meta.evaluator;
   if(document.getElementById('import-bank')?.checked&&ctx.meta.questionBank)next.questionBank=validateBank(ctx.meta.questionBank);
   persist(next);document.getElementById('dialog').close();view='dashboard';render();notify(`${ctx.cases.length} casos importados.`);return;
  }
  if(name==='reapply'){
   const newCase=C.reapply(c);persist({...state,cases:[newCase,...state.cases],currentCaseId:newCase.id});activeId=newCase.id;tab='capture';page=0;seqItem=1;aiInput='';render();notify('Nueva aplicación creada; el protocolo anterior permanece en su caso.');return;
  }
  if(name==='answer'){
   const item=+el.dataset.item,value=+el.dataset.value,responses={...c.responses};if(value)responses[item]=value;else delete responses[item];
   mutate(c.id,{responses});
   if(captureMode==='seq'&&value){seqItem=Math.min(567,item+1);}
   const focused=el.getAttribute('aria-label');render();if(captureMode==='grid'&&focused)document.querySelectorAll('[data-action="answer"],[data-response-item]').forEach(b=>{if(b.getAttribute('aria-label')===focused)b.focus({preventScroll:true});});return;
  }
  if(name==='capture-grid'||name==='capture-seq'){captureMode=name==='capture-grid'?'grid':'seq';render();return;}
  if(name==='page-prev'||name==='page-next'){page+=name==='page-next'?1:-1;render();return;}
  if(name==='seq-prev'||name==='seq-next'){seqItem=Math.min(567,Math.max(1,seqItem+(name==='seq-next'?1:-1)));render();return;}
  if(name==='jump'){const value=+document.getElementById('jump-item').value;if(!Number.isInteger(value)||value<1||value>567)throw new Error('El ítem debe estar entre 1 y 567.');onlyPending=false;page=Math.floor((value-1)/30);seqItem=value;render();return;}
  if(name==='finish'){
   const n=count(c);if(n.registered<567){const first=Array.from({length:567},(_,i)=>i+1).find(i=>![1,2,3].includes(c.responses[i]));onlyPending=false;page=Math.floor((first-1)/30);seqItem=first;render();throw new Error(`Quedan ${567-n.registered} ítems por registrar. Continúe desde el ítem ${first}; use O para una omisión deliberada.`);}
   mutate(c.id,{completedAt:new Date().toISOString(),status:'finalizada'});tab='results';render();notify('Aplicación finalizada. Revise la validez y las puntuaciones.');return;
  }
  if(name==='template'){IO.save(IO.template(c,state.questionBank),IO.filename(c)+'_cuestionario.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');return;}
  if(name==='import-responses'){document.getElementById('file-responses').click();return;}
  if(name==='responses-import-confirm'){
   const mode=document.getElementById('response-import-mode').value,ctx=dialogContext,responses=mode==='replace'?ctx.result.responses:{...c.responses,...ctx.result.responses};
   mutate(c.id,{responses});document.getElementById('dialog').close();tab='capture';page=0;render();notify(`${ctx.result.count} respuestas incorporadas.`);return;
  }
  if(name==='previous-edit'){previousEditor();return;}
  if(name==='previous-save'){
   const data=Object.fromEntries(new FormData(document.getElementById('previous-form'))),scores=R.previous(data.text);
   if(!scores.length)throw new Error('No se identificaron T. Use código=T, por ejemplo D=70, Hs=65.');
   mutate(c.id,{previousAssessment:{...data,scores,completedAt:'Transcripción documentada'},patient:{...c.patient,previousMMPI2:data.text}});document.getElementById('dialog').close();render();notify('Comparación anterior guardada.');return;
  }
  if(name==='compare-normalize'){
   const prev=c.previousAssessment,p=c.patient,result=A.score(prev.responses,p.sex,p.baremo,p.calculationSource||'manual');
   mutate(c.id,{previousAssessment:{...prev,originalParameters:{baremo:prev.baremo,sex:prev.sex,calculationSource:prev.calculationSource,scores:prev.scores},baremo:p.baremo,sex:p.sex,calculationSource:p.calculationSource||'manual',scores:result.scores,normalizedAt:new Date().toISOString()}});render();notify('La referencia previa se recalculó con los parámetros actuales. Sus parámetros originales se conservan en el JSON.');return;
  }
  if(name==='prompt-preview'||name==='prompt-copy'||name==='prompt-download'){
   const p=R.buildPrompt(reportCase(),c.patient.baremo,promptOptions);
   if(name==='prompt-preview')dialog('Prompt preparado',`<div class="prompt-preview">${esc(p)}</div>`,btn('Cerrar','dialog-close'),{type:'prompt'});
   else if(name==='prompt-download')IO.save(p,IO.filename(c)+'_prompt_IA.txt','text/plain;charset=utf-8');
   else{try{await navigator.clipboard.writeText(p);notify('Prompt copiado.');}catch(e){dialog('Copiar prompt',`<p>Seleccione el texto y cópielo con Ctrl+C o Cmd+C.</p><textarea id="clipboard-fallback" class="control" style="height:300px">${esc(p)}</textarea>`,btn('Cerrar','dialog-close'),{type:'prompt'});const t=document.getElementById('clipboard-fallback');t.focus();t.select();}}
   return;
  }
  if(name==='import-ai'){document.getElementById('file-ai').click();return;}
  if(name==='ai-save'){
   const text=R.normalizeInput(aiInput);R.validate(text,reportCase());const marked=R.withAI(c,text);
   persist({...state,cases:state.cases.map(x=>x.id===c.id?marked:x)});tab='report';render();notify('Integración guardada. Revise el informe completo.');return;
  }
  if(name==='ai-review'){if(!c.aiContextualizedReport)throw new Error('Primero guarde la integración de IA.');R.validate(c.aiContextualizedReport,reportCase());mutate(c.id,{aiReviewedAt:new Date().toISOString()});render();notify('Revisión profesional registrada.');return;}
  if(name.startsWith('export-')){
   const format=name.slice(7),rc=reportCase();
   if(format==='xlsx'){IO.save(IO.exportReport(rc,state.evaluator),IO.filename(c)+'_informe.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}
   else await R.download(format,rc,state.evaluator);notify(format==='pdf'?'Informe preparado para imprimir o guardar como PDF.':'Archivo preparado para descargar.');return;
  }
  if(name==='clinical-save'){
   const value=key=>document.getElementById('f-'+key).value;
   const patient={...c.patient};
   for(const [key] of clinicalFields){
    const text=value(key);
    if(text||Object.hasOwn(patient,key))patient[key]=text;
   }
   const interviewSufficient=document.getElementById('f-interviewSufficient').checked;
   if(interviewSufficient||Object.hasOwn(patient,'interviewSufficient'))patient.interviewSufficient=interviewSufficient;
   mutate(c.id,{patient,clinicalSummary:value('clinicalSummary'),recommendations:value('recommendations')});
   render();notify('Aportes clínicos guardados.');return;
  }
  if(name==='settings-save'){
   const form=document.getElementById('evaluator-form');if(!form.reportValidity())return;const evaluator={...state.evaluator,...Object.fromEntries(new FormData(form))};persist({...state,evaluator});render();notify('Datos del evaluador guardados.');return;
  }
  if(name==='signature-upload'){document.getElementById('file-signature').click();return;}
  if(name==='signature-remove'){persist({...state,evaluator:{...state.evaluator,signature:null}});render();return;}
  if(name==='bank-reset'){persist({...state,questionBank:validateBank(root.MMPI2QuestionBank.questions)});render();notify('Cuestionario incluido restaurado.');return;}
  if(name==='bank-upload'){document.getElementById('file-bank').click();return;}
  if(name==='archive'){
   persist({...state,cases:state.cases.map(x=>x.id===c.id?{...x,archivedAt:x.archivedAt?null:new Date().toISOString()}:x)});render();notify(c.archivedAt?'Caso recuperado.':'Caso archivado. Puede recuperarlo desde el filtro Archivados.');return;
  }
  if(name==='history-view'){
   const r=c.previousReports[+el.dataset.index];dialog('Versión anterior del caso',`<p class="case-meta">${esc(r.reason||'Versión previa')} · ${date(r.recordedAt)}</p>${r.aiContextualizedReport?`<div class="narrative">${esc(r.aiContextualizedReport)}</div>`:'<p>Esta versión no incluye texto de integración.</p>'}${table(['Escala','PD','T'],(r.scores||[]).map(s=>[esc(s.code),s.raw??'—',esc(s.t_display??s.T??'—')]))}`,btn('Cerrar','dialog-close'),{type:'history'});return;
  }
  if(name==='history-restore'){
   const r=c.previousReports[+el.dataset.index];if(!r.responses)throw new Error('Esta versión no conserva respuestas para restaurar.');
   mutate(c.id,{responses:{...r.responses},patient:{...c.patient,...r.patient},completedAt:null,aiContextualizedReport:'',aiSourceSignature:null,aiReviewedAt:null});tab='capture';aiInput='';render();notify('Respuestas y datos restaurados. Revise y vuelva a finalizar la aplicación.');return;
  }
  if(name==='install'){
   if(installEvent){await installEvent.prompt();installEvent=null;return;}
   notify(location.protocol==='file:'?'La instalación requiere un sitio HTTPS o localhost. Puede usar la app desde este archivo.':/iPad|iPhone/.test(navigator.userAgent)?'En Safari, pulse Compartir y Añadir a pantalla de inicio.':'Use el menú del navegador: Instalar aplicación o Crear acceso directo.');return;
  }
 }
 function validateBank(value){
  const values=Array.isArray(value)?value.map(q=>[q.id,q.text]):Object.entries(value||{}),bank={};
  for(const [i,text]of values){if(!Number.isInteger(+i)||+i<1||+i>567||typeof text!=='string'||!text.trim()||text.length>3000||bank[i])throw new Error('Los enunciados deben tener números únicos 1–567 y texto no vacío.');bank[i]=text.trim();}
  if(Object.keys(bank).length!==567)throw new Error('El banco de enunciados debe contener los 567 ítems.');return bank;
 }
 document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;
  event.preventDefault();const name=el.dataset.action;
  if(name.startsWith('export-'))el.classList.add('loading');
  try{await action(name,el);}catch(e){notify(e.message||'No se pudo completar la acción.',true);console.error(e);}finally{el.classList.remove('loading');}
 });
 document.addEventListener('submit',e=>e.preventDefault());
 document.addEventListener('input',e=>{
  const el=e.target;if(el.id==='search'){query=el.value;document.getElementById('case-list').innerHTML=casesList();}
  if(el.id==='ai-input')aiInput=el.value;
  if(el.id==='f-ai-focus')promptOptions.focus=el.value;
 });
 document.addEventListener('change',async e=>{
  const el=e.target;
  try{
   if(el.dataset.responseItem){await action('answer',{dataset:{item:el.dataset.responseItem,value:el.value},getAttribute:()=>el.getAttribute('aria-label')});return;}
   if(el.id==='case-filter'){filter=el.value;render();}
   if(el.id==='only-pending'){onlyPending=el.checked;page=0;render();}
   if(el.id==='result-group'){group=el.value;render();}
   if(el.id==='f-ai-mode')promptOptions.mode=el.value;
   if(el.id==='ai-anonymize')promptOptions.anonymize=el.value==='yes';
   if(el.dataset.reportOption&&!el.disabled){
    const c=get(),key=el.dataset.reportOption;
    mutate(c.id,{reportOptions:S.changeOption(c,key,el.checked)});
    render();document.querySelector(`[data-report-option="${key}"]`)?.focus({preventScroll:true});
   }
   const file=el.files?.[0];if(!file)return;
   if(el.id==='file-cases'){
    if(file.size>40000000)throw new Error('El respaldo excede 40 MB. Importe los casos por separado.');
    const source=JSON.parse(await file.text()),meta=source.state||source,cases=C.normalizeCases(source),duplicates=cases.filter(c=>state.cases.some(s=>s.id===c.id)).length;
    dialog('Importar casos',`<p><b>${cases.length} casos</b> identificados en ${esc(file.name)}.</p><p class="case-meta">${duplicates} tienen un identificador ya existente.</p><div class="field"><label for="import-mode">Cuando un caso ya existe</label><select id="import-mode"><option value="copy">Conservar ambos como casos separados</option><option value="update">Actualizar el existente y conservar una versión previa</option></select></div>${meta.evaluator?'<p><label><input id="import-settings" type="checkbox" checked> Importar también los datos del evaluador</label></p>':''}${meta.questionBank?'<p><label><input id="import-bank" type="checkbox" checked> Importar también el banco de enunciados</label></p>':''}`,btn('Cancelar','dialog-close')+btn('Importar','cases-import-confirm','primary'),{type:'case-import',cases,meta});
   }
   if(el.id==='file-responses'){
    const result=await IO.readResponses(file);dialog('Revisar importación de respuestas',`<p><b>${result.count} respuestas</b> válidas. ${result.omitted} omisiones deliberadas.</p><p class="case-meta">${esc(file.name)} · No se ha cambiado el caso todavía.</p><div class="field"><label for="response-import-mode">Cómo incorporar las respuestas</label><select id="response-import-mode"><option value="merge">Añadir o actualizar los ítems importados</option><option value="replace">Reemplazar toda la hoja del caso</option></select></div>`,btn('Cancelar','dialog-close')+btn('Aplicar respuestas','responses-import-confirm','primary'),{type:'responses-import',result});
   }
   if(el.id==='file-ai'){aiInput=await R.readFile(file);tab='ai';render();notify('Texto importado. Revíselo y pulse Guardar integración.');}
   if(el.id==='file-bank'){const bank=validateBank(await IO.readBank(file));persist({...state,questionBank:bank});render();notify('567 preguntas incorporadas para la app y el Excel.');}
   if(el.id==='file-signature'){
    if(file.size>1000000)throw new Error('Use una firma PNG, JPG o WebP menor de 1 MB.');
    if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Formato de firma no compatible.');
    const value=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});
    persist({...state,evaluator:{...state.evaluator,signature:value}});render();notify('Firma incorporada.');
   }
  }catch(error){notify(error.message||'No se pudo importar el archivo.',true);console.error(error);}finally{if(el.type==='file')el.value='';}
 });
 document.addEventListener('keydown',e=>{
  if(view!=='case'||tab!=='capture'||captureMode!=='seq'||document.getElementById('dialog').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;
  const val={v:1,'1':1,f:2,'2':2,o:3,'3':3}[e.key.toLowerCase()];
  if(val){e.preventDefault();action('answer',{dataset:{item:String(seqItem),value:String(val)},getAttribute:()=>null}).catch(error=>notify(error.message,true));}
  if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();action(e.key==='ArrowLeft'?'seq-prev':'seq-next',{});}
 });
 window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
 window.addEventListener('online',render);window.addEventListener('offline',render);
 window.addEventListener('storage',e=>{if(e.key==='mmpi2-app-storage'){try{state=C.load().state;render();notify('Los casos se actualizaron desde otra pestaña.');}catch(error){notify(error.message,true);}}});
 if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(error=>console.warn('PWA no disponible:',error.message));
 root.MMPI2App={getState:()=>state,getCase:get,reportCase,render};
 render();
})(globalThis);
